M_FALSOS=dict(id='m14-desafio-falsos-amigos',title='Desafio: falsos amigos e vocabulário',lead='Leia a frase em inglês e escolha o sentido correto da palavra-chave em português.',
 labels=['biblioteca','livraria','atualmente','na verdade','por fim','eventualmente','fingir','pretender'],
 items=[("The project imports an open-source library.",0,"Library = biblioteca de código. Livraria é bookstore."),
 ("The bookstore sells technical manuals.",1,"Bookstore = livraria."),
 ("The server is currently offline.",2,"Currently = atualmente."),
 ("The server is actually working; the problem is the network.",3,"Actually = na verdade, de fato. Não significa atualmente."),
 ("Eventually, the update finished and the system restarted.",4,"Eventually = por fim, no final das contas."),
 ("Occasionally, the service fails during peak hours.",5,"Occasionally = eventualmente, de vez em quando."),
 ("Do not pretend that the warning does not exist.",6,"Pretend = fingir. Pretender é intend."),
 ("We intend to migrate to version 2 next month.",7,"Intend = pretender, ter a intenção de.")])
M_MODAL=dict(id='m14-desafio-modais',title='Desafio: MUST, SHOULD ou MAY?',lead='Leia a frase de especificação e escolha a força da exigência, conforme a RFC 2119.',
 labels=['MUST (obrigatório)','MUST NOT (proibido)','SHOULD (recomendado)','MAY (opcional)'],
 items=[("The client MUST send the API key in every request.",0,"MUST: requisito absoluto."),
 ("Passwords MUST NOT be stored in plain text.",1,"MUST NOT: proibição absoluta."),
 ("Clients SHOULD cache the response for at least one minute.",2,"SHOULD: recomendado; pode haver razões válidas para não seguir."),
 ("The server MAY include the optional X-Request-Id header.",3,"MAY: verdadeiramente opcional."),
 ("The field id is REQUIRED.",0,"REQUIRED equivale a MUST (RFC 2119, item 1)."),
 ("The field nickname is OPTIONAL.",3,"OPTIONAL equivale a MAY (RFC 2119, item 5)."),
 ("Tokens SHALL NOT be shared between users.",1,"SHALL NOT equivale a MUST NOT (RFC 2119, item 2)."),
 ("It is RECOMMENDED to use HTTPS.",2,"RECOMMENDED equivale a SHOULD (RFC 2119, item 3)."),
 ("Users SHOULD enable two-factor authentication.",2,"SHOULD: recomendação."),
 ("The service SHALL respond within 30 seconds.",0,"SHALL equivale a MUST (RFC 2119, item 1).")])
GLOSS=[('Skimming','Leitura rápida para captar a ideia geral do texto.'),('Scanning','Leitura dirigida para achar uma informação específica.'),('Main idea','Ideia principal: o que resume o texto inteiro.'),('Inference','Inferência: conclusão permitida pelo texto sem ser dita literalmente.'),
 ('Connective','Conectivo: palavra que liga ideias e indica contraste, causa, consequência, adição ou exemplo.'),('Phrasal verb','Verbo composto por verbo e partícula (turn off, set up).'),('False friend','Falso amigo: palavra parecida com uma do português, mas de sentido diferente (library, actually).'),
 ('Deprecated','Obsoleto: ainda funciona, mas será removido em versão futura.'),('Endpoint','Endereço de uma API que recebe requisições.'),('Request / response','Pedido do cliente e resposta do servidor.'),('Payload','Conteúdo (corpo) enviado ou recebido em uma requisição ou resposta.'),
 ('Rate limiting','Limite de requisições por período; ao exceder, 429 Too Many Requests.'),('Idempotent','Método HTTP cujas requisições idênticas repetidas têm o mesmo efeito que uma só (PUT, DELETE e métodos seguros).'),('Safe method','Método HTTP de semântica essencialmente de leitura (GET, por exemplo).'),
 ('MUST / SHOULD / MAY','Palavras de exigência da RFC 2119: obrigatório, recomendado e opcional.'),('Semantic versioning','Versionamento MAJOR.MINOR.PATCH: incompatível, funcionalidade compatível, correção.'),('Changelog / release notes','Lista de mudanças por versão (Added, Changed, Deprecated, Removed, Fixed, Security).'),
 ('Backward compatible','Retrocompatível: não quebra o que funcionava na versão anterior.'),('Language-agnostic','Independente de linguagem de programação.'),('Self-contained','Autocontido: traz o que precisa para funcionar.'),('Workaround','Solução alternativa para um problema.'),('Timeout','Tempo limite de espera por uma resposta.')]
